function u8(buf, offset) {
    return buf[offset] & 0xFF;
}

function s16(buf, offset) {
    let val = (buf[offset] & 0xFF) | ((buf[offset + 1] & 0xFF) << 8);
    return val > 32767 ? val - 65536 : val;
}

let state = {
