function getBit(buf, bitIndex) {
    const byteIndex = Math.floor(bitIndex / 8);
    const bitOffset = bitIndex % 8;
    if (byteIndex >= buf.length) return false;
    return ((buf[byteIndex] >> bitOffset) & 0x01) === 1;
}

let state = {
    kind: "PcsTimeoutsState",
    version: 1,
    timestampUtc: new Date().toISOString(),
    pcs_dcOcProtTout: getBit(data, 0),
    pcs_acOvProtTout: getBit(data, 1),
    pcs_acUvProtTout: getBit(data, 2),
    pcs_acOcProtTout: getBit(data, 3),
    pcs_modOvertProtTout: getBit(data, 4),
    pcs_ccCvRechgVTout: getBit(data, 5),
    pcs_batCvChgVTout: getBit(data, 6),
    pcs_cvChgMaxTimeTout: getBit(data, 7),
    pcs_cvToFloatCurrTout: getBit(data, 8),
    pcs_floatChgVTout: getBit(data, 9),
    pcs_floatToCcCurrTout: getBit(data, 10),
